class Tag:
    def __init__(self, tag_type, elements):
        self.tag_type = tag_type
        self.elements = elements

    def serialize(self, stream):
        StreamIO.write_ubyte(stream, self.tag_type.TYPE_ID)
        StreamIO.write_int(stream, len(self.elements))
        for element in self.elements:
            self.tag_type.write(stream, element)

    @staticmethod
    def deserialize(stream, tag_type):
        tag_type_id = StreamIO.read_ubyte(stream)
        if tag_type_id != tag_type.TYPE_ID:
            raise ValueError("Invalid tag type ID")
        num_elements = StreamIO.read_int(stream)
        elements = [tag_type.read(stream) for _ in range(num_elements)]
        return Tag(tag_type, elements)

import requests
from typing import Any, Dict, Tuple
import time


def make_post_request(url: str, data: Any, headers: Dict[str, str], data_format: str, retries: int = 5) -> Tuple[int, Any]:
    if data_format not in ('json', 'xml', 'text'):
        raise ValueError("Invalid data format, please choose 'json', 'xml', or 'text'")

    if data_format == 'json':
        headers['Content-Type'] = 'application/json'
        try:
            import json
            data_payload = json.dumps(data)
        except ValueError as e:
            raise ValueError(f"Failed to convert JSON data: {e}")

    elif data_format == 'xml':
        headers['Content-Type'] = 'application/xml'
        # Assuming data is already an XML string
        data_payload = data

    else:
        headers['Content-Type'] = 'text/plain'
        data_payload = data

    delay = 1
    for i in range(retries + 1):
        try:
            response = requests.post(url, data=data_payload, headers=headers)
            response.raise_for_status()  # Raise exception for bad status codes
            return response.status_code, response.content

        except (requests.RequestException, requests.Timeout) as e:
            if i == retries:
                raise ValueError("POST request failed after maximum retries")
            else:
                time.sleep(delay)
                delay *= 2
                continue
        except Exception as e:
            raise e

