import math

def is_prime(number):
    if number < 2:
        return False

    for i in range(2, int(math.sqrt(number)) + 1):
        if number % i == 0:
            return False

    return True

def prime_factors(number):
    factors = []

    for i in range(2, int(math.sqrt(number)) + 1):
        while number % i == 0:
            factors.append(i)
            number = number // i

    if number > 1:
        factors.append(number)

    return factors

def check_prime(number):
    if is_prime(number):
        return True, []
    else:
        return False, prime_factors(number)

from datetime import datetime
import pytz

def get_datetime(timezone='local', dt_format='dmy_hms'):

    # Define valid inputs
    valid_timezones = pytz.all_timezones
    valid_formats = ['dmy_hms', 'iso8601', 'rfc2822']

    # Validate timezone
    if timezone != 'local':
        if timezone not in valid_timezones:
            raise ValueError(f'Invalid timezone. Please use one of: {valid_timezones}')

    # Validate date time format
    if dt_format not in valid_formats:
        raise ValueError(f'Invalid date time format. Please use one of: {valid_formats}')

    # Get current date and time
    if timezone == 'local':
        current_datetime = datetime.now()
    else:
        current_datetime = datetime.now(pytz.timezone(timezone))

    # Format date and time
    if dt_format == 'dmy_hms':
        str_datetime = current_datetime.strftime('%A, %d %B %Y %I:%M:%S %p')
    elif dt_format == 'iso8601':
        str_datetime = current_datetime.isoformat()
    elif dt_format == 'rfc2822':
        str_datetime = current_datetime.strftime('%a, %d %b %Y %H:%M:%S %z')

    print(str_datetime)

