def is_valid_ipv6(ip_str):
    # Check if the string contains a double colon
    if ip_str.count('::') > 1:
        return False

    # Split the string by colons to get the groups
    groups = ip_str.split(':')

    # Check if the number of groups is correct
    if len(groups) != 8 and '::' not in groups:
        return False

    # Iterate over each group
    for group in groups:
        # Check if the group is empty and not the double colon
        if group == '':
            continue

        # Check if the group is a valid hexadecimal number
        try:
            int(group, 16)
        except ValueError:
            return False

        # Check if the group is within the range of 0000 to FFFF
        if len(group) > 4:
            return False

    return True

